"use client";

import MainMenu from "@components/layout/main-menu";
import { useAppContext } from "@providers/AppContext";
import { useRef, useState, useEffect } from "react";
import { useTheme } from "@providers/ThemeProvider";
import Image from "next/image";
import UsernameSideCard from "@components/ui/cards/username-side-card";
import { LuSquareLibrary } from "react-icons/lu";
import { LuImage } from "react-icons/lu";
import { MdHistoryEdu } from "react-icons/md";
import { IoCreate } from "react-icons/io5";
import { LuSearch } from "react-icons/lu";


export default function Sidebar() {
  const { theme } = useTheme();
  const darkTheme = theme === "dark";

  const {
    toggleSearch,
    toggleMainMenu,
    mainMenuVisible,
    setMainMenuVisible,
    sidebarExpanded,
    toggleSidebar,
  } = useAppContext();

  const sidebarRef = useRef<HTMLDivElement | null>(null);
  const mainMenuRef = useRef<HTMLDivElement | null>(null);
  const mainMenuToggleBtnRef = useRef<HTMLDivElement | null>(null);

  // Sidebar empty-area click (ONLY when collapsed)
  const handleSidebarClick = (e: React.MouseEvent) => {
    if (!sidebarExpanded) {
      const target = e.target as HTMLElement;

      // Ignore clicks on buttons, icons, links
      if (target.closest("button, i, a")) return;

      toggleSidebar();
    }
  }

  // Close Main Menu on outside click
  useEffect(() => {
    const closeIfOutside = (e: MouseEvent) => {
      if (
        mainMenuVisible &&
        mainMenuRef.current &&
        !mainMenuRef.current.contains(e.target as Node) &&
        !mainMenuToggleBtnRef.current?.contains(e.target as Node)
      ) {
        setMainMenuVisible(false);
      }
    };
    window.addEventListener("click", closeIfOutside);
    return () => window.removeEventListener("click", closeIfOutside);
  }, [mainMenuVisible]);

  const sidebarItems = [
    {
      label: "New Chat",
      icon: <IoCreate className="min-w-[20px] min-h-[20px]" />,
      onClick: null,
    },
    {
      label: "Search Chat",
      icon: <LuSearch className="min-w-[20px] min-h-[20px]" />,
      onClick: toggleSearch,
    },
    {
      label: "Library",
      icon: <LuSquareLibrary className="min-w-[20px] min-h-[20px]" />,
      onClick: toggleSearch,
    },
    {
      label: "Images",
      icon: <LuImage className="min-w-[20px] min-h-[20px]" />,
      onClick: toggleSearch,
    },
    {
      label: "Chat History",
      icon: <MdHistoryEdu className="min-w-[20px] min-h-[20px]" />,
      onClick: toggleSearch,
    },
  ];

  return (
    <div
      ref={sidebarRef}
      onClick={handleSidebarClick}
      className={`
        relative h-full bg-bg flex flex-col
        transition-all duration-500 ease-in-out
        ${sidebarExpanded ? "w-[245px]" : "cursor-w-resize w-[60px]"}
      `}
    >
      {/* Logo + Collapse Button */}
      <div className="p-4 flex items-center justify-between">
        <Image
          src={`/logos/${darkTheme ? "white_triangle" : "black_triangle"}.png`}
          alt="Woah AI"
          width={30}
          height={30}
        />
        {sidebarExpanded && (
          <div className="text-text transition hover:bg-bg-hover rounded-full cursor-pointer w-[25px] h-[25px] ">
            <button
              onClick={toggleSidebar}
              className="cursor-pointer w-[25px] h-[25px] flex items-center justify-center"
            >
              <i className="bx bx-chevron-left text-xl" />
            </button>
          </div>
        )}
      </div>

      {/* Menu */}
      <div className="flex-1 flex flex-col justify-between px-2 py-4">
        <div className="flex flex-col gap-2 h-auto">
          {sidebarItems.map((item, idx) => (
            <div
              key={idx}
              className={`flex items-center px-2 w-auto h-auto rounded-[10px] truncate 
                cursor-pointer text-text overflow-hidden hover:bg-bg-hover transition-all duration-300
                ease-in-out ${sidebarExpanded ? "gap-3" : "gap-0 justify-center"}`}
              onClick={item.onClick || undefined}
            >
              <div className="flex items-center justify-center w-auto h-[35px]">
                {item.icon}
              </div>
              <span
                className={`flex items-center justify-start transition-discrete text-sm font-medium truncate transition-opacity duration-300 w-[200px] h-[35px]
                  ${sidebarExpanded ? "opacity-100 flex" : "opacity-0 hidden"}
                `}
              >
                {item.label}
              </span>
            </div>
          ))}
        </div>

        {/* Profile */}
        <div
          onClick={toggleMainMenu}
          className="flex mx-3 items-center gap-3 cursor-pointer text-text"
        >
          <UsernameSideCard />
        </div>
      </div>
      
    </div>
  );
}
